def tarjan_scc(n={{n}}, g={{graph}}):
    idx = [0]; stk = []; on_stack = [False]*n
    index = [-1]*n; low = [0]*n; sccs = []
    def strongconnect(v):
        call = [(v, iter(g[v]))]
        index[v] = low[v] = idx[0]; idx[0] += 1
        stk.append(v); on_stack[v] = True
        while call:
            u, it = call[-1]
            try:
                w = next(it)
                if index[w] == -1:
                    index[w] = low[w] = idx[0]; idx[0] += 1
                    stk.append(w); on_stack[w] = True
                    call.append((w, iter(g[w])))
                elif on_stack[w]:
                    low[u] = min(low[u], index[w])
            except StopIteration:
                call.pop()
                if call: low[call[-1][0]] = min(low[call[-1][0]], low[u])
                if low[u] == index[u]:
                    comp = []
                    while True:
                        x = stk.pop(); on_stack[x] = False; comp.append(x)
                        if x == u: break
                    sccs.append(comp)
    for v in range(n):
        if index[v] == -1: strongconnect(v)
    return sccs
